"""Create optimized documentation images from the rendered showcase.

Run ``python examples/showcase.py`` and ``python examples/geometry_check.py``
first, then run this script from the repository root. The large artifacts stay
untracked; only the optimized images in docs/images are intended for Git.
"""

from __future__ import annotations

from pathlib import Path

from PIL import Image

ROOT = Path(__file__).resolve().parents[1]
ARTIFACTS = ROOT / "artifacts"
OUTPUT = ROOT / "docs" / "images"
GAP = 24

# The inputs are trusted images generated by this repository's examples.
Image.MAX_IMAGE_PIXELS = None


def resize_to_width(image: Image.Image, width: int) -> Image.Image:
    height = round(image.height * width / image.width)
    return image.resize((width, height), Image.Resampling.LANCZOS)


def load_comparison(slug: str, width: int) -> Image.Image:
    path = ARTIFACTS / "showcase" / "comparisons" / f"{slug}.png"
    with Image.open(path) as source:
        return resize_to_width(source.convert("RGB"), width)


def save(image: Image.Image, name: str, width: int) -> None:
    OUTPUT.mkdir(parents=True, exist_ok=True)
    resized = resize_to_width(image, width)
    destination = OUTPUT / name
    resized.save(destination, optimize=True)
    print(f"Saved {destination.relative_to(ROOT)} ({destination.stat().st_size / 1024:.0f} KiB)")


def make_overview() -> None:
    slugs = ("01-line", "07-rounded-bars", "12-heatmap", "24-3d-scatter")
    images = [load_comparison(slug, 1200) for slug in slugs]
    row_heights = (
        max(images[0].height, images[1].height),
        max(images[2].height, images[3].height),
    )
    overview = Image.new(
        "RGB",
        (2 * 1200 + GAP, sum(row_heights) + 3 * GAP),
        "white",
    )
    positions = (
        (0, 0),
        (1200 + GAP, 0),
        (0, row_heights[0] + GAP),
        (1200 + GAP, row_heights[0] + GAP),
    )
    for image, position in zip(images, positions, strict=True):
        overview.paste(image, position)
        image.close()
    save(overview, "overview.png", 1800)
    overview.close()


def make_capsules() -> None:
    with Image.open(ARTIFACTS / "capsule-geometry.png") as source:
        save(source.convert("RGB"), "capsules.png", 1600)


def make_contact_sheet() -> None:
    with Image.open(ARTIFACTS / "showcase" / "00-contact-sheet.png") as source:
        save(source.convert("RGB"), "contact-sheet.png", 1800)


def main() -> None:
    make_overview()
    make_capsules()
    make_contact_sheet()


if __name__ == "__main__":
    main()
